<div class="row g-3">
  <div class="col-12"><div class="card custom-card"><div class="card-body d-flex justify-content-between align-items-center"><div><h4 class="mb-1">FMS Storage</h4><p class="text-muted mb-0">Bucket: fms-private · User: <?= esc((string)($storageUser['fms_storage_username'] ?? '')) ?></p></div><a href="<?= esc(site_url('fms-storage/logout'),'attr') ?>" class="btn btn-outline-danger">Logout</a></div></div></div>
  <div class="col-12"><div class="card custom-card"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Object Browser</h5><div><label class="btn btn-primary mb-0"><i class="ph-duotone ph-upload-simple"></i> Upload<input id="fmsStorageFile" type="file" hidden></label><button id="fmsStorageRefresh" class="btn btn-light ms-2">Refresh</button></div></div><div class="card-body"><div id="fmsStorageMessage" class="alert d-none"></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Object</th><th>Type</th><th>Size</th><th>Updated</th><th class="text-end">Action</th></tr></thead><tbody id="fmsStorageObjects"><tr><td colspan="5" class="text-center text-muted">Memuat...</td></tr></tbody></table></div></div></div></div>
</div>
<script>
(function(){
 const api='<?= esc(site_url('api/v1/storage'),'js') ?>'; const body=document.getElementById('fmsStorageObjects'); const msg=document.getElementById('fmsStorageMessage');
 function show(text,ok=false){msg.textContent=text;msg.className='alert '+(ok?'alert-success':'alert-danger');}
 async function call(url,opt={}){const r=await fetch(url,{credentials:'same-origin',...opt});const j=await r.json();if(!r.ok||!j.status)throw new Error(j.message||'Request gagal');return j;}
 function fmt(n){return n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB'}
 async function load(){try{const j=await call(api+'/objects');body.innerHTML='';(j.data.objects||[]).forEach(o=>{const tr=document.createElement('tr');tr.innerHTML='<td><i class="ph-duotone ph-file me-2"></i>'+o.key+'</td><td>'+o.mime+'</td><td>'+fmt(o.size)+'</td><td>'+o.updated_at+'</td><td class="text-end"><button class="btn btn-sm btn-outline-primary share" data-key="'+encodeURIComponent(o.key)+'">Share</button> <button class="btn btn-sm btn-outline-danger delete" data-key="'+encodeURIComponent(o.key)+'">Hapus</button></td>';body.appendChild(tr)});if(!body.children.length)body.innerHTML='<tr><td colspan="5" class="text-center text-muted">Bucket kosong.</td></tr>';}catch(e){show(e.message)}}
 document.getElementById('fmsStorageRefresh').onclick=load;
 document.getElementById('fmsStorageFile').onchange=async e=>{if(!e.target.files[0])return;const f=new FormData();f.append('file',e.target.files[0]);try{await call(api+'/objects',{method:'POST',body:f});show('Upload berhasil.',true);load()}catch(x){show(x.message)}e.target.value=''};
 body.onclick=async e=>{const key=decodeURIComponent(e.target.dataset.key||'');if(e.target.classList.contains('delete')){if(confirm('Hapus object ini?')){try{await call(api+'/objects',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})});load()}catch(x){show(x.message)}}}if(e.target.classList.contains('share')){try{const j=await call(api+'/share',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,ttl:3600})});await navigator.clipboard.writeText(j.data.url);show('Share URL disalin.',true)}catch(x){show(x.message)}}}; load();
})();
</script>
